CREATE TABLE IF NOT EXISTS "LicensePayment" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "licenseId" UUID NOT NULL, "method" TEXT NOT NULL, "amount" DECIMAL(18,2) NOT NULL, "status" TEXT NOT NULL DEFAULT 'PENDING', "referenceNumber" TEXT NOT NULL UNIQUE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("id"));
